package com.example.statusdrafter.service; import com.example.statusdrafter.entity.*; import com.example.statusdrafter.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class NotificationService {private final NotificationRepository repo; private final TaskRepository tasks; private final StatusUpdateRepository updates; public NotificationService(NotificationRepository r,TaskRepository t,StatusUpdateRepository u){repo=r;tasks=t;updates=u;} public List<Notification> mine(User u){refresh(u);return repo.findByUserOrderByCreatedAtDesc(u);} public long unread(User u){refresh(u);return repo.countByUserAndReadStatusFalse(u);} public void read(Long id,User u){Notification n=repo.findById(id).orElseThrow();if(n.getUser().getId().equals(u.getId())){n.setReadStatus(true);repo.save(n);}} private void refresh(User u){LocalDate today=LocalDate.now();for(Task t:tasks.findByDeadlineBetweenAndEmployeeOrderByDeadlineAsc(today,today.plusDays(2),u)) if(repo.findByUserOrderByCreatedAtDesc(u).stream().noneMatch(n->n.getMessage().contains("Deadline approaching: "+t.getId())))repo.save(new Notification(u,"Deadline approaching: "+t.getTaskName()+" ("+t.getDeadline()+")","DEADLINE"));for(Task t:tasks.findByDeadlineBeforeAndStatusNotAndEmployeeOrderByDeadlineAsc(today,Task.Status.COMPLETED,u)) if(repo.findByUserOrderByCreatedAtDesc(u).stream().noneMatch(n->n.getMessage().contains("Overdue: "+t.getId())))repo.save(new Notification(u,"Overdue: "+t.getTaskName()+" was due "+t.getDeadline(),"OVERDUE"));if(updates.countByEmployeeAndUpdateDate(u,today)==0 && today.getDayOfWeek()!=DayOfWeek.SUNDAY)if(repo.findByUserOrderByCreatedAtDesc(u).stream().noneMatch(n->n.getMessage().contains("Submit today's status")))repo.save(new Notification(u,"Submit today's status update.","STATUS_REMINDER"));}}
